"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["11658"],{80670(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>o,contentTitle:()=>r,toc:()=>l,assets:()=>h});var n=JSON.parse('{"id":"tianya/antifake","title":"","description":"Today I actually saw in the Casual Talk section \'Japan rises in the east, shining upon all of China,\' wanting Chinese netizens to match it with a lower couplet.\\" How is the internet getting more and more boring? My original \\"Japan rises in the east, shining across Shikoku and Kyushu\\" has, after more than two years, actually become \\"Japan rises in the east, shining upon all of China\\" -- such a tasteless thing. You should know that Shikoku and Kyushu are occupied Japanese territories, and of course also carry the meanings of \\"Four Countries\\" (China, Japan, North Korea, South Korea) and \\"Nine Provinces\\" (an ancient name for China). Actually this was meant sarcastically -- Japan wanted to dominate the \\"Four Countries and Nine Provinces,\\" but instead had its own Shikoku and Kyushu occupied. Look at this blindly altered version -- too boring.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/antifake.md","sourceDirName":"tianya","slug":"/tianya/antifake","permalink":"/en/tianya/antifake","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"antifake","title":"","hide_table_of_contents":true,"sidebar_label":"Impostors must be exposed, setting the record straight \u2014 how has the so-called Japanese first couplet this lady posted been altered again?"},"sidebar":"tianyaSidebar","previous":{"title":"Mining disasters are unavoidable; blind sympathizers are all hypocrites \u2014 laughable, pathetic, pitiable. (Note: also titled on Qiangguo: The vicious cycle of mining disasters must be broken)","permalink":"/en/tianya/minedisasters"},"next":{"title":"Li Weifeng \u2014 a busty player who lives off his stinking feet \u2014 what\'s there to be proud of?","permalink":"/en/tianya/lwf"}}'),s=a(74848),i=a(28453);let o={id:"antifake",title:"",hide_table_of_contents:!0,sidebar_label:"Impostors must be exposed, setting the record straight \u2014 how has the so-called Japanese first couplet this lady posted been altered again?"},r='Imposters Must Be Struck Down -- Setting the Record Straight: How Did the So-Called "Japanese Upper Couplet" That This Lady Created Get Its Face Changed Again?',h={},l=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"imposters-must-be-struck-down----setting-the-record-straight-how-did-the-so-called-japanese-upper-couplet-that-this-lady-created-get-its-face-changed-again",children:'Imposters Must Be Struck Down -- Setting the Record Straight: How Did the So-Called "Japanese Upper Couplet" That This Lady Created Get Its Face Changed Again?'})}),"\n",(0,s.jsx)(t.p,{children:'Today I actually saw in the Casual Talk section: "Currently various websites are \'Commemorating the 60th Anniversary of Victory in the War of Resistance.\' On the Lianhe Zaobao BBS, a Japanese person came to a Chinese website to \'challenge the house,\' posing a provocatively challenging upper couplet: \'Japan rises in the east, shining upon all of China,\' wanting Chinese netizens to match it with a lower couplet." How is the internet getting more and more boring? My original "Japan rises in the east, shining across Shikoku and Kyushu" has, after more than two years, actually become "Japan rises in the east, shining upon all of China" -- such a tasteless thing. You should know that Shikoku and Kyushu are occupied Japanese territories, and of course also carry the meanings of "Four Countries" (China, Japan, North Korea, South Korea) and "Nine Provinces" (an ancient name for China). Actually this was meant sarcastically -- Japan wanted to dominate the "Four Countries and Nine Provinces," but instead had its own Shikoku and Kyushu occupied. Look at this blindly altered version -- too boring.'}),"\n",(0,s.jsx)(t.p,{children:"Of course this lady mainly used this couplet to tease the leftists on Qiangguo Forum. Let me repost two posts from over two years ago -- see for yourselves:"}),"\n",(0,s.jsxs)(t.p,{children:["First: ",(0,s.jsx)("br",{}),'\nUpper couplet "Japan rises in the east, shining across Shikoku and Kyushu" -- the leftists of Qiangguo Forum can\'t just stand by and watch. If you can match it better than this little lady, this little lady is willing to not speak for two days.']}),"\n",(0,s.jsxs)(t.p,{children:["First: Japan rises in the east, shining across Shikoku and Kyushu; The Celestial Dynasty revives, its momentum swallowing Five Rams and Sanya. ",(0,s.jsx)("br",{}),'\n"Celestial Dynasty" refers to China, and can also be split into "Heaven -- Dynasty"; "Five Rams" refers to Guangzhou, but can also secretly mean the whole world; "Sanya" is the one in Hainan, and also refers to East Asia, Southeast Asia, and Northeast Asia. This approach mainly starts from the nation, and in momentum it shouldn\'t be worse than little Japan\'s upper couplet, though it has a bit of a "swallowing the globe" vibe. It\'s purely couplet fun -- don\'t take it too seriously for now.']}),"\n",(0,s.jsxs)(t.p,{children:["Second: Japan rises in the east, shining across Shikoku and Kyushu; Dogen returns empty, his source returns to Yunmen and Fayan. ",(0,s.jsx)("br",{}),'\nDogen was the founder of Japan\'s Soto Zen school, who went to study in Song Dynasty China and returned. Since Chan has nothing to attain, his return was "empty." "Dogen" can also be read as "Dao -- Yuan"; as for "Yunmen" and "Fayan," each is one of the Five Schools of Chan Buddhism and also the names of two great Chan masters. Although there aren\'t numbers matching numbers here, since Shikoku and Kyushu form a pair, and Yunmen and Fayan also form a pair, it can be accommodated in couplet form. This lower couplet takes a cultural perspective -- meaning little Japan, your culture all came from China, so stop your nonsense.']}),"\n",(0,s.jsxs)(t.p,{children:["Second: ",(0,s.jsx)("br",{}),"\nFrom June 9th to today is exactly one month, and it's time to leave. If during this time on the forum I've offended any moderators or users, I apologize here first. But first I must reveal the truth about that \"Japanese upper couplet.\" Everyone first look at this record: ",(0,s.jsx)("br",{}),"\nPen name: \u65E5\u65E5\u65E5\u65E5\u65E5\u65E5\u65E5\u672C ",(0,s.jsx)("br",{}),"\nRegistration date: 2003-05-31"]}),"\n",(0,s.jsx)(t.p,{children:'This was a pseudonym this little lady once used. This upper couplet was thought up by this little lady while traveling in Rizhao. The lower couplet was also composed at the time and was posted for fun on different websites. It was posted on the China-Japan Forum on June 1st -- at the time I even mistyped "shining across" as "across shining." These can all be verified; the records are still there, and the moderators can attest to this since this little lady registered with the same email. It was purely for fun at the time, just hoping to remind fellow Chinese to appreciate their own culture. I never expected that the day before yesterday someone in Deep Water reposted from a Singaporean newspaper, and it became known worldwide. The internet these days is truly too powerful. This little lady\'s couplet: "Japan rises in the east, shining across Shikoku and Kyushu; Dogen returns empty, enlightenment through Yunmen and Fayan" was originally designed alongside "Three Luminaries: sun, moon, and stars; Four Odes: feng, ya, song" -- completely out of respect for culture. That things turned out this way, this little lady didn\'t expect at all. It seems the power of the internet was still underestimated. These past two days this little lady was squeezing out fun like toothpaste from a tube, purely hoping to introduce more knowledge about couplets. So this little lady hereby solemnly declares: this matter ends here, don\'t play anymore. If not for that repost the day before yesterday, this little lady wouldn\'t have wanted to bring it up at all. "Japan rises in the east, shining across Shikoku and Kyushu; Dogen returns empty, enlightenment through Yunmen and Fayan" and "Three Luminaries: sun, moon, and stars; Four Odes: feng, ya, song" both contain the implicit meaning that culture triumphs over force, and it\'s also a reminder to Japan -- even if you want to play tricks with military force, Chinese culture will ultimately prevail over you. Another original intention of this affair was to remind all Chinese to cherish their own culture, for this is the ultimate driving force of the Chinese nation\'s prosperity.'})]})}function d(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,t,a){a.d(t,{R:()=>o,x:()=>r});var n=a(96540);let s={},i=n.createContext(s);function o(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);